import { buttonClasses } from '@mui/material/Button';
import type { Theme } from '@mui/material/styles';
import type {
  CSSSelectorObjectOrCssVariables,
  SystemCssProperties,
  SystemStyleObject,
} from '@mui/system';
import { svTokens } from '../../theme/tokens';
import {
  buttonColors,
  buttonFocus,
  buttonReducedMotion,
  buttonSize,
} from '../shared/button-shared';
import type { SvButtonAppearance, SvButtonProps } from './sv-button';

export interface SvButtonState extends SvButtonProps {
  appearance: SvButtonAppearance;
  hasColor: boolean;
  loadingMode: 'mui' | 'stripes' | 'text';
}

// One 24px gradient cycle projected onto the horizontal animation axis.
const stripePeriod = 24 / Math.sin(Math.PI / 3);

const hidden: SystemStyleObject<Theme> = {
  position: 'absolute',
  width: '1px',
  height: '1px',
  padding: 0,
  overflow: 'hidden',
  clipPath: 'inset(50%)',
  whiteSpace: 'nowrap',
};

export function buttonStyles(
  theme: Theme,
  state: SvButtonState
): SystemStyleObject<Theme> {
  const palette = (theme.vars ?? theme).palette;
  const tokens = svTokens(theme);
  const {
    appearance,
    variant,
    size,
    color = 'primary',
    hasColor,
    loading,
    loadingMode,
    loadingPosition,
  } = state;
  const preset = appearance !== 'default' && !hasColor;
  const compactText = variant === 'text';
  const length = buttonSize(size);
  const { main, hover, contrast } = buttonColors(theme, color);
  let background = color === 'inherit' ? palette.action.hover : main;
  let hoveredBackground = color === 'inherit' ? palette.action.selected : hover;
  let foreground = contrast;
  let hoveredForeground = foreground;
  let accent = main;
  let accentHover = hover;
  if (preset) {
    switch (appearance) {
      case 'secondary':
        background = `var(--SvButton-surface, ${tokens.surface})`;
        hoveredBackground = `var(--SvButton-surfaceHover, ${tokens.surfaceHover})`;
        foreground = palette.text.primary;
        break;
      case 'tooltip':
        background = hoveredBackground = '#fff';
        foreground = '#000';
        break;
      case 'server':
      case 'serverSecondary':
      case 'nerf':
      case 'nerfSecondary': {
        const green = appearance.startsWith('nerf');
        const light = appearance.endsWith('Secondary');
        const center = green ? tokens.green : tokens.accent;
        const edge = light ? (green ? '#eff5f1' : '#f1eff5') : '#2f2f2f';
        background = `radial-gradient(ellipse 51.9% 203.571% at 51.9% 212.5%, ${center}, ${edge})`;
        hoveredBackground = `radial-gradient(ellipse 61.9% 242.857% at 51.9% 212.5%, ${center}, ${edge})`;
        foreground = light ? '#000' : '#fff';
      }
    }
    hoveredForeground =
      appearance === 'tooltip' ? 'rgba(0,0,0,0.7)' : foreground;
    accent = foreground;
    accentHover = hoveredForeground;
  }
  const nativeCenter =
    loading && loadingMode === 'mui' && loadingPosition === 'center';
  const rootForeground = variant === 'contained' ? foreground : accent;
  const styles: SystemCssProperties<Theme> &
    CSSSelectorObjectOrCssVariables<Theme> = {
    fontFamily: theme.typography.fontFamily ?? 'Inter, sans-serif',
    textTransform: 'none',
    fontWeight: 500,
    fontSize: size === 'large' ? '15px' : '13px',
    lineHeight: '24px',
    letterSpacing: '-0.0025em',
    borderRadius: '8px',
    boxSizing: 'border-box',
    minWidth: 0,
    padding: `${(length - 24) / 2}px ${size === 'small' ? 8 : size === 'large' ? 16 : 12}px`,
    position: 'relative',
    isolation: 'isolate',
    overflow: 'hidden',
    '& .SvButton-label': {
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
    },
    [`& .${buttonClasses.startIcon}`]: { marginLeft: 0, marginRight: '6px' },
    [`& .${buttonClasses.endIcon}`]: { marginRight: 0, marginLeft: '6px' },
    [`& .${buttonClasses.icon} > :nth-of-type(1)`]: {
      fontSize: '16px',
      width: '16px',
      height: '16px',
    },
    [`&.${buttonClasses.focusVisible}`]: buttonFocus(theme),
    [`&.${buttonClasses.disabled}`]: { opacity: loading ? 1 : 0.5 },
    // MUI gives center loaders a concrete color while the button text is transparent.
    [`& .${buttonClasses.loadingIndicator}`]:
      nativeCenter && color === 'inherit' ? {} : { color: rootForeground },
  };
  if (variant === 'contained' || variant === 'outlined' || variant === 'text') {
    Object.assign(styles, {
      color: nativeCenter ? 'transparent' : rootForeground,
      background: variant === 'contained' ? background : 'transparent',
      '&:hover': {
        background: variant === 'contained' ? hoveredBackground : 'transparent',
        color: nativeCenter
          ? 'transparent'
          : variant === 'contained'
            ? hoveredForeground
            : accentHover,
      },
      [`&.${buttonClasses.disabled}`]: {
        opacity: loading ? 1 : 0.5,
        color: nativeCenter ? 'transparent' : rootForeground,
        background: variant === 'contained' ? background : 'transparent',
      },
    });
  }
  if (variant === 'outlined') {
    Object.assign(styles, {
      border: `1px solid ${accent}`,
      padding:
        size === 'small'
          ? '1px 7px'
          : size === 'large'
            ? '9px 15px'
            : '5px 11px',
    });
  }
  if (compactText)
    Object.assign(styles, {
      padding: 0,
      borderRadius: 0,
      fontSize: size === 'large' ? '15px' : '12px',
      lineHeight: size === 'large' ? '24px' : '16px',
      letterSpacing: 0,
    });
  if (preset && appearance === 'secondary' && variant === 'contained') {
    styles[`&.${buttonClasses.disabled}`] = {
      opacity: 1,
      background: hoveredBackground,
      color: nativeCenter ? 'transparent' : foreground,
      ...(!loading
        ? { [`& .SvButton-label, & .${buttonClasses.icon}`]: { opacity: 0.5 } }
        : {}),
    };
  }
  if (loading && loadingMode === 'stripes') {
    Object.assign(styles, {
      [`&.${buttonClasses.disabled}`]: {
        opacity: 1,
        color: foreground,
        background,
      },
      '&::before': {
        content: '""',
        position: 'absolute',
        inset: '0 auto 0 0',
        width: `calc(100% + ${stripePeriod}px)`,
        height: '100%',
        zIndex: 0,
        pointerEvents: 'none',
        backgroundImage: `repeating-linear-gradient(60deg, transparent 0 12px, ${hoveredBackground} 12px 24px)`,
        animation: 'sv-button-stripes 1s linear infinite',
      },
      '@keyframes sv-button-stripes': {
        to: { transform: `translateX(-${stripePeriod}px)` },
      },
      [`& .SvButton-label, & .${buttonClasses.icon}`]: {
        position: 'relative',
        zIndex: 1,
      },
      [`& .${buttonClasses.loadingIndicator}`]: hidden,
    });
  }
  if (loading && loadingMode === 'text') {
    styles['& .SvButton-label'] = hidden;
    styles[`& .${buttonClasses.icon}`] = { display: 'none' };
    if (loadingMode === 'text')
      Object.assign(styles, {
        width: state.fullWidth ? '100%' : '16px',
        height: '16px',
        padding: 0,
      });
  }
  if (loadingMode === 'mui' && loadingPosition !== 'center') {
    // Align MUI's spinner with our 16px icons and 6px icon gap.
    const inset = compactText
      ? 0
      : (size === 'small' ? 8 : size === 'large' ? 16 : 12) -
        (variant === 'outlined' ? 1 : 0);
    styles[`& .${buttonClasses.loadingIndicator}`] = {
      color: rootForeground,
      ...(state.fullWidth
        ? {
            position: 'relative',
            width: 0,
            left: loadingPosition === 'start' ? '-22px' : '6px',
            right: 'auto',
            '& > *': { flexShrink: 0 },
          }
        : { [loadingPosition === 'start' ? 'left' : 'right']: `${inset}px` }),
    };
  }
  styles['@media (prefers-reduced-motion: reduce)'] = buttonReducedMotion;
  return styles;
}
